// Helper: Format Currency
const formatCurrency = (num: number) => {
  if (isNaN(num)) return "NT$ 0";
  return "NT$ " + new Intl.NumberFormat('en-US', { 
      minimumFractionDigits: 0, 
      maximumFractionDigits: 0 
  }).format(num);
};

// Helper: Process and compress image
const processImage = (file: File, callback: (result: string) => void) => {
  const reader = new FileReader();
  reader.onload = (e) => {
    const img = new window.Image();
    img.onload = () => {
      const canvas = document.createElement('canvas');
      let width = img.width;
      let height = img.height;

      // Resize if too large (e.g. > 400px) to save Firestore space
      const MAX_SIZE = 400;
      if (width > height) {
        if (width > MAX_SIZE) {
          height *= MAX_SIZE / width;
          width = MAX_SIZE;
        }
      } else {
        if (height > MAX_SIZE) {
          width *= MAX_SIZE / height;
          height = MAX_SIZE;
        }
      }

      canvas.width = width;
      canvas.height = height;
      const ctx = canvas.getContext('2d');
      if (ctx) {
        ctx.drawImage(img, 0, 0, width, height);
        callback(canvas.toDataURL('image/png', 0.8));
      }
    };
    img.src = e.target?.result as string;
  };
  reader.readAsDataURL(file);
};

// Component: Auto-resizing Textarea
const AutoHeightTextarea: React.FC<React.TextareaHTMLAttributes<HTMLTextAreaElement>> = ({ style, value, ...props }) => {
  const textareaRef = useRef<HTMLTextAreaElement>(null);

  useLayoutEffect(() => {
      if (textareaRef.current) {
          textareaRef.current.style.height = 'auto';
          textareaRef.current.style.height = textareaRef.current.scrollHeight + 'px';
      }
  }, [value]);

  return (
      <textarea
          ref={textareaRef}
          style={{ ...style, resize: 'none', overflow: 'hidden' }}
          value={value}
          {...props}
      />
  );
};

