              </button>
          </div>
        </div>
      </header>

      {/* --- Main Content --- */}
      <main className="mt-8 print:mt-0">
        <QuotationPreview 
          data={quotation} 
          setData={setQuotation}
          updateItem={updateItem}
          addItem={addItem}
          deleteItem={deleteItem}
        />
      </main>

      {/* --- Overlay for Click Outside Menu --- */}
      {showFileMenu && (
        <div 
          className="fixed inset-0 z-20 bg-transparent" 
