  addItem: () => void;
  deleteItem: (id: number) => void;
}

// Helper: Format Currency
const formatCurrency = (num: number) => {
  if (isNaN(num)) return "NT$0";
  return "NT$" + new Intl.NumberFormat('en-US', { 
      minimumFractionDigits: 0, 
      maximumFractionDigits: 0 
  }).format(num);
};

// Helper: Process and compress image
const processImage = (file: File, callback: (result: string) => void) => {
  const reader = new FileReader();
  reader.onload = (e) => {
    const img = new window.Image();
    img.onload = () => {
      const canvas = document.createElement('canvas');
      let width = img.width;
      let height = img.height;

      const MAX_SIZE = 400;
      if (width > height) {
        if (width > MAX_SIZE) {
          height *= MAX_SIZE / width;
          width = MAX_SIZE;
        }
      } else {
        if (height > MAX_SIZE) {
          width *= MAX_SIZE / height;
          height = MAX_SIZE;
        }
      }

      canvas.width = width;
      canvas.height = height;
      const ctx = canvas.getContext('2d');
      if (ctx) {
        ctx.drawImage(img, 0, 0, width, height);
        callback(canvas.toDataURL('image/png', 0.8));
      }
    };
    img.src = e.target?.result as string;
  };
  reader.readAsDataURL(file);
};

// Component: Auto-resizing Textarea
const AutoHeightTextarea: React.FC<React.TextareaHTMLAttributes<HTMLTextAreaElement> & { autoResize?: boolean }> = ({ style, value, autoResize = true, ...props }) => {
  const textareaRef = useRef<HTMLTextAreaElement>(null);

  useLayoutEffect(() => {
      if (autoResize && textareaRef.current) {
          textareaRef.current.style.height = 'auto';
          textareaRef.current.style.height = textareaRef.current.scrollHeight + 'px';
      }
  }, [value, autoResize]);

  return (
      <textarea
          ref={textareaRef}
          style={{ ...style, resize: autoResize ? 'none' : 'vertical', overflow: autoResize ? 'hidden' : 'auto' }}
          value={value}
          {...props}
      />
  );
};

// Component: Editable Price Cell
const EditablePriceCell: React.FC<{ value: number; onChange: (val: number) => void }> = ({ value, onChange }) => {
    const [isEditing, setIsEditing] = useState(false);
    const inputRef = useRef<HTMLInputElement>(null);

    useEffect(() => {
        if (isEditing && inputRef.current) {
            inputRef.current.focus();
            inputRef.current.select();
        }
    }, [isEditing]);

    if (isEditing) {
        return (
            <div className="flex items-start justify-end w-full h-full pt-[2px]">
                 <input 
                    ref={inputRef}
                    type="number"
                    className="text-right w-24 bg-white outline-none border-b border-blue-500 m-0 p-0 text-black font-medium leading-tight" 
                    value={value === 0 ? '' : value} 
                    onChange={(e) => onChange(parseFloat(e.target.value) || 0)}
                    onBlur={() => setIsEditing(false)}
                    onKeyDown={(e) => {
                        if (e.key === 'Enter') setIsEditing(false);
                    }}
                    placeholder="0"
                />
            </div>
        );
    }

    return (
        <div 
            onClick={() => setIsEditing(true)}
            className="text-right w-full cursor-text hover:bg-gray-100 rounded px-1 font-medium text-black h-full flex items-start justify-end pt-[2px] leading-tight"
        >
            {formatCurrency(value)}
        </div>
    );
};

